-- The site is for the Kyiv branch: the Zhytomyr store leaves the shop settings (contacts, footer, header, pickup,
-- structured data), and the company pages mention only the Kyiv store and service area.
update public.site_settings
set value = (select jsonb_agg(store order by position) from jsonb_array_elements(value) with ordinality as list(store, position) where store ->> 'id' <> 'zhytomyr'),
    updated_at = now()
where key = 'stores' and value @> '[{"id": "zhytomyr"}]';

update public.site_pages set body = '[{"type":"heading","text":"Хто ми"},{"type":"paragraph","text":"«Софіївка» починала з котельних систем і досі вважає їх своєю головною спеціалізацією. Сьогодні ми ведемо весь шлях обладнання: допомагаємо обрати, постачаємо, встановлюємо, запускаємо й обслуговуємо його після гарантії."},{"type":"paragraph","text":"Серед наших клієнтів власники будинків і квартир, забудовники, монтажники, проєктанти й архітектори. Ми розраховуємо на довгу співпрацю, тому радимо те, що підходить саме вашому об’єкту."},{"type":"heading","text":"Що ми гарантуємо"},{"type":"list","ordered":false,"items":["Лише офіційна продукція з гарантією та сервісною підтримкою в Україні.","2 роки гарантії на монтажні роботи.","Гарантія виробника, допомога з гарантійним зверненням, післягарантійне обслуговування.","Підбір за технічними параметрами й консультація фахівця перед покупкою."]},{"type":"heading","text":"Як ми працюємо"},{"type":"list","ordered":false,"items":["Сертифіковані фахівці регулярно проходять навчання й тренінги виробників.","Власний сервісний центр обслуговує котли та інженерні системи.","Власне виробництво комплектуючих для котельного обладнання.","Комплектуючі й аксесуари до основного обладнання в одному місці.","Доставка по всій Україні."]},{"type":"heading","text":"Бренди"},{"type":"paragraph","text":"Співпрацюємо з виробниками, яким довіряємо: Termojet, Buderus, BAXI, Wilo, Grundfos, Ecosoft, TEKK HAUS, Altep, FENIKS, FOCUS, TECH та іншими."},{"type":"heading","text":"Магазин"},{"type":"paragraph","text":"с. Софіївська Борщагівка, вул. Київська, 3. Пн–Пт 9:00–18:00, Сб 9:00–14:00."}]'::jsonb, seo_description = 'ТД «Софіївка»: з 2000 року продаємо, монтуємо й обслуговуємо інженерні системи. Магазин у Софіївській Борщагівці під Києвом, офіційна продукція, гарантія, доставка по Україні.' where slug = 'about';
update public.site_pages set lead = 'Обслуговуємо й ремонтуємо газові, твердопаливні та електричні котли й теплові насоси. Майстри виїжджають по Києву та Київській області.' where slug = 'service-center';
